#!/usr/bin/env node
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash, randomUUID } from 'node:crypto';
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { z } from 'zod';
import { commandSchemas, commandLabels, readCommands, validateCommand } from '../shared/commands.mjs';
import { generationSchema, jobIdSchema } from '../shared/generation.mjs';
import { MAX_PROJECT_BUNDLE_BYTES, PROJECT_MIME } from './project-routes.mjs';
import { PSD_EXPORT_LIMITS, PSD_MIME_TYPE } from './psd-export.mjs';
import { registerPsdImportTools } from './psd-import-mcp.mjs';
import { registerColorLookupTools } from './color-lookup-mcp.mjs';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const dataDir=path.resolve(process.env.PRISM_DATA_DIR||path.join(root,'.prism'));
const companion=process.env.PRISM_URL||'http://127.0.0.1:43120';
const address=new URL(companion);
if(address.protocol!=='http:' || !['127.0.0.1','localhost'].includes(address.hostname) || address.username || address.password)throw new Error('PRISM_URL must point to a local HTTP companion service.');

async function request(route,body){
  let token;
  try{token=(await fs.readFile(path.join(dataDir,'bridge-token'),'utf8')).trim();}
  catch{throw new Error('Start the Prism companion with npm run dev or npm start before using its editing tools.');}
  let response;
  try{response=await fetch(new URL(route,companion),{method:body?'POST':'GET',headers:{Authorization:`Bearer ${token}`,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(100_000),redirect:'error'});}
  catch{throw new Error('The local Prism companion is unavailable or timed out. If an edit was in progress, inspect the document before retrying.');}
  const data=await response.json();
  if(!response.ok || data.ok===false)throw Object.assign(new Error(data.error?.message||'The Prism request failed.'),{code:data.error?.code});
  return route==='/api/command'?data.result:data;
}
function textResult(data){return{content:[{type:'text',text:JSON.stringify(data)}],structuredContent:data};}
function failure(error){return{isError:true,content:[{type:'text',text:JSON.stringify({code:error.code||'PRISM_ERROR',message:error.message,...(error.report?{report:error.report}:{})})}]};}

async function projectRequest(route,{data,requestId,mimeType=PROJECT_MIME,maxBytes=MAX_PROJECT_BUNDLE_BYTES}={}){
  let token;
  try{token=(await fs.readFile(path.join(dataDir,'bridge-token'),'utf8')).trim();}
  catch{throw new Error('Start the local Prism companion before transferring projects.');}
  let response;
  try{response=await fetch(new URL(route,companion),{method:data?'POST':'GET',headers:{Authorization:`Bearer ${token}`,...(data?{'Content-Type':PROJECT_MIME,'X-Prism-Request-Id':requestId}:{})},...(data?{body:data}:{}),signal:AbortSignal.timeout(100_000),redirect:'error'});}
  catch{throw new Error('The project transfer was interrupted. For imports, retry the exact same file with the same requestId to avoid duplicate projects.');}
  if(!response.ok){const error=await response.json();throw Object.assign(new Error(error.error?.message||'The project transfer failed.'),{code:error.error?.code,...(error.report?{report:error.report}:{})});}
  if(data)return response.json();
  if(response.headers.get('content-type')!==mimeType)throw new Error('The companion did not return the requested export format.');
  const declared=Number(response.headers.get('content-length'));
  if(!Number.isSafeInteger(declared)||declared<1||declared>maxBytes){await response.body?.cancel();throw new Error('The exported file exceeds its transfer limit.');}
  const chunks=[];let size=0;
  for await(const chunk of response.body){size+=chunk.length;if(size>declared||size>maxBytes)throw new Error('The exported file exceeds its declared file size.');chunks.push(Buffer.from(chunk));}
  if(size!==declared)throw new Error('The project download was incomplete.');
  return{data:Buffer.concat(chunks,size),revision:Number(response.headers.get('x-prism-revision')),filename:response.headers.get('content-disposition')?.match(/filename="([^"]+)"/)?.[1]||'Project.prism'};
}
const backend=z.literal('native').default('native').describe('The standalone Prism editing engine.');
const instructions=`Prism Studio is a local layered image editor. Start with prism_status, then prism_list_documents and prism_get_document. Inspect prism_get_preview to see the actual image. Use stable document/layer IDs and expectedRevision from the latest document when modifying it. Group related changes in prism_apply_transaction for one undo step. Check capabilities and never claim unsupported features worked. Re-read state after stale revision errors. Mutations accept requestId for retry deduplication during the companion session. Never automatically retry with a new requestId. Native supports painting/retouching, geometric and exact pixel masks, composite-channel selections, curves/levels and editable typography, subject to advertised capabilities. Image generation and edits use asynchronous prism_generate_image and prism_edit_image jobs. The default provider is codex. Inspect prism_ai_status: when the local Codex worker is enabled, new jobs are queued for automatic pickup every five seconds, generated with its built-in image tool and returned locally. Jobs with automation queued/generating/returning belong to that worker: poll them; never also generate their image yourself. Legacy manual jobs without automation can use prism_get_generation_handoff, this conversation’s built-in image tool and prism_complete_generation. The worker runs a separate local signed-in Codex session; it does not awaken this hosted conversation. Only explicit provider=openai sends requests to the separately configured billable Images API. Use prism_ai_status first, preserve requestId, and never automatically regenerate failed or interrupted jobs. Selection edits are hard-clipped locally outside the saved selection. Results are added as separate layers; stale results stay ready until explicitly applied using the latest revision. For protected-person compositions, generate the background separately and composite original cutouts above it; do not ask generation to recreate the people. Native local alpha segmentation, protected cutouts, proportional cross-document placement, outside outlines and bundled Fraunces text are available; segmentation needs the local model installed. RAW, PSB and general Photoshop document interpretation are not implemented. Limited PSD v1 import uses prism_inspect_psd_import_file then prism_import_psd_file for supported flat RGB8 raster layers and simple masks, with raw/PackBits channels. Require a complete supported report, preserve its SHA-256/importerVersion/options and reuse the stable requestId after an uncertain response. Untagged RGB requires an explicit sRGB interpretation; unknown profiles remain unsupported. The original PSD is archived separately and downloadable with prism_export_original_psd. Limited layered PSD export uses prism_inspect_psd_export and prism_export_psd; unsupported features reject explicitly. Use .prism portable projects for full native graph/asset retention. For separate clone/heal repairs, use create_repair_layer above an explicit root raster and paint_stroke with a declared sampling scope; Current & below plus ignoreAdjustments excludes upper artwork and standalone grades while preserving protected writes. Healing uses sampled color matching and is not generative removal. Preserve editable text/adjustment layers through update commands; don't duplicate an adjustment when revising its value. Use paint layers for brush additions; eraser/retouch require a raster target. Rasterization removes text editability in the current state but remains undoable. Native projects auto-save editable layers; export creates a separate flattened image file. Use selections or explicit masks to protect untouched pixels. Use prism_import_file to import a user-selected local raster image without sending base64 through context.`;

const server=new McpServer({name:'prism-studio',version:'0.1.0'},{instructions});
server.registerTool('prism_status',{title:'Prism connection status',description:'Inspect the native image editor, available commands, limitations, and recent edit activity.',inputSchema:z.object({}).strict(),annotations:{readOnlyHint:true,openWorldHint:false}},async()=>{try{return textResult(await request('/api/status'));}catch(error){return failure(error);}});
server.registerTool('prism_tool_catalog',{
  title:'Browse editing tool coverage',description:'Read the sourced Photoshop toolbar checklist plus separately marked Prism Native tools. Partial means working core behavior with stated limits. Planned means unavailable. Native entries are not Adobe toolbar claims. Check backend capabilities before editing.',
  inputSchema:z.object({category:z.string().optional(),implementedOnly:z.boolean().default(false)}).strict(),annotations:{readOnlyHint:true,openWorldHint:false,idempotentHint:true},
},async({category,implementedOnly})=>{try{
  const entries=JSON.parse(await fs.readFile(new URL('../shared/tool-catalog.json',import.meta.url),'utf8'));
  const selected=entries.filter(entry=>(!category||entry.category.toLowerCase().includes(category.toLowerCase()))&&(!implementedOnly||entry.status!=='planned'));
  return textResult({researchedAt:'2026-09-18',total:entries.length,photoshopReferenceCount:entries.filter(entry=>entry.engine!=='native').length,nativeExtensionCount:entries.filter(entry=>entry.engine==='native').length,tools:selected});
}catch(error){return failure(error);}});

const hueSaturationDetails = ' Native targeted Hue / Saturation is kind hue_saturation with value0 in global adjustments and source filters. Require hueSaturationPolicy=rgb-hue-triangle-hsl-v1 and hueSaturationRanges containing master,reds,yellows,greens,cyans,blues,magentas, plus the individual context kind/command and source coordinates for filters. Each optional named row is [Hue degrees,Saturation percent,Lightness percent]: Hue -180..180, S/L -100..100, all finite in exact0.01-unit increments. Defaults are seven zero rows. Partial updates replace complete supplied tuples and retain omitted rows; recipes normalize complete settings and reset omitted/default rows on an existing target. Conventional encoded-RGB8 HSL uses the original input hue for all range contributions, including alongside Master changes. Hue and Saturation use adjacent hue-normalized weights; named Lightness additionally fades with original chroma/255, while Master is unweighted. Aggregate Saturation/Lightness clamp after all rows; Hue wraps the summed shift. Saturation is proportional: +100 doubles current HSL saturation up to its limit, while -100 at full influence gives HSL-lightness gray (pure red255 becomes gray128), not Rec709 grayscale. Gray cannot be colorized by Hue/Saturation. Named Lightness endpoints can be weaker on dark/pale/near-gray input; Master Lightness endpoints reach white/black and can reveal existing color noise near those endpoints. This is a fixed native HSL policy, not Adobe pixel parity, perceptual exposure, Colorize or editable hue falloffs. Final conversion has a fixed binary64 operation order and byte rounding; exact mathematical half ties can differ by one byte, with no runtime rational fallback. Alpha and hidden RGB remain exact; existing candidate blend/opacity, completed-stack mask, geometry and protection follow. Computing source entries cost32 visits per pixel, all21 authored-zero controls cost1, inactive entries cost0; nonzero cancelling/full-turn settings still cost32. Existing nonnormal blend adds40 and an active effect mask8. A Normal computing source reaches the384-million work limit at12MP (masked9.6MP) before other limits. All-zero is only a candidate identity and retains blending/protection/source-edit guards. Original assets remain unchanged.';
const selectiveColorDetails = ' Native Selective Color uses kind selective_color and value0 in both adjustments and source filters. Require selectiveColorPolicy=rgb-partition-cmyk-v1, selectiveColorMethods containing relative and absolute, and selectiveColorRanges containing reds,yellows,greens,cyans,blues,magentas,whites,neutrals,blacks, plus the individual context kind/command and source coordinates for filters. Parameters are optional method=relative|absolute and nine optional named rows [Cyan%,Magenta%,Yellow%,Black%], each finite -100..100 in exact0.01% increments. Defaults are Relative with every row zero. Updates replace each supplied complete four-value row and retain all omitted rows/method. Native encoded-RGB partitions observe the original entry pixel and sum all range contributions before one clamp/round. Positive CMY reduces corresponding RGB; Black adds equally to virtual CMY, not physical ink separation. Relative scales existing complementary amounts, cannot change pure white, and positive Black may leave a saturated primary unchanged; Absolute can change white and darken primaries. This is RGB8 correction, not CMYK/profile conversion or Adobe pixel parity. Alpha and hidden RGB remain exact, followed by existing blend/opacity, completed-stack mask, geometry and protection. Computing source entries cost12 visits per pixel; all36 authored controls zero cost1, disabled/opacity0 cost0. Nonzero cancelling controls still cost12. Existing nonnormal blend adds40 and an active effect mask8. All-zero is only a candidate identity: nonnormal blending and structural protection/source-edit guards still apply. Recipes save complete method/rows, so sparse defaults reset omitted settings when applied.';
const curvesDetails = ' Native Curves accepts optional parameters.interpolation=linear|smooth with value0,2–16 strictly increasing finite points from x0 to255, and channel rgb/red/green/blue. Require curvesInterpolationPolicy=shape-preserving-pchip-v1 and curvesInterpolationModes containing smooth before choosing Smooth. Omitted mode defaults to legacy Linear on add; partial updates retain omitted points/channel/mode, and explicit linear resets Smooth. A points update replaces the complete list. Canonical Linear omits the field. Smooth compiles a shape-preserving native PCHIP curve to a256-byte lookup with exact authored integer knots; it permits plateaus/reversals and arbitrary finite point spacing. Binary64 rounding can differ from exact-real interpolation and from legacy Linear at two-point half ties. This is not Adobe algorithm parity or high-depth processing. Source filters preserve every alpha byte and hidden RGB; global Curves retains its existing hidden-RGB grading policy. Existing masks, protection, blending, Bake and geometry rules remain. Saved recipes retain the full effective mode; applying a canonical Linear adjustment recipe explicitly resets a Smooth target. Native independent channel banks require curvesBanksPolicy=master-byte-then-channel-byte-v1 and a complete curvesBankNames list: master,red,green,blue. Use the existing curves kind/value0 with parameters {mode:banks,banks:{master?,red?,green?,blue?}}; each bank accepts points and interpolation with the existing bounds. Missing banks default Linear identity on creation; canonical bank metadata saves all four complete records and explicit interpolation. Master is evaluated to a byte before the matching component lookup; entry blend/opacity apply once afterward. Any Smooth bank requires the separate Smooth capability, even when another bank is selected. Existing single-curve records are unchanged. For updates, banks payloads always need explicit mode:banks; omitted banks and bank fields retain current values, and supplied points replace the full bank point list. Empty parameters are a no-op. Switching representations replaces with submitted/default settings: mode:banks alone creates identity banks; mode:single explicitly returns to submitted/default legacy settings. Old-style points/channel/interpolation patches cannot implicitly discard a banked record. To preserve a single curve during upgrade, copy its points/interpolation into master for rgb or the matching component, with other banks identity. Arbitrary banks cannot be losslessly collapsed to one curve; explicit mode:single discards all bank settings. Complete recipes reset every bank or explicitly replace banked targets with legacy settings without changing saved old recipe hashes. Banked source work stays1 per pixel plus blend/mask weights, with1280 bytes peak table storage and768 retained; original alpha and distinct legacy source/global hidden-RGB rules are unchanged.';

const filterBlendDetails = ' Optional source-filter blendMode uses the independently advertised layerFilterBlendPolicy=candidate-rgb-v1 and layerFilterBlendModes, plus source coordinates and the individual filter kind/policy. There are 26 RGB modes including Normal; Dissolve is unsupported here. This is separate from the whole-layer blend mode and is not a global adjustment field. The existing full-strength byte candidate blends against the current input RGB, then filter opacity fades that result. No extra alpha factor or early blend-byte rounding is applied. Every alpha byte and zero-alpha RGB remain exact. Normal preserves legacy pixels/work and is omitted on canonical authoring; update omission preserves the current mode, while explicit normal removes its stored field. Existing externally supplied explicit-normal records can remain until an ordinary filter edit. Twenty nonnormal modes use exact byte ratios and half-up rounding at the exact authored binary64 opacity, with a bounded near-half exact fallback; Soft Light and Hue/Saturation/Color/Luminosity use the defined native floating formulas. Nonseparable luma uses0.3R+0.59G+0.11B, not the grading luma. Filter threshold/zero-amount/sigma identities describe the candidate: a nonnormal blend can still change RGB when the candidate equals its input. Disabled or zero-opacity entries bypass both stages. Every enabled positive-opacity nonnormal entry adds40 weighted source visits per pixel to the existing candidate cost, including hidden layers and identity candidates. Thus an identity costs41S and computing Add Noise48S; all share384million visits. No opacity-dependent surcharge or new full-image plane is added. Changing mode alone revalidates the complete graph; refusals leave settings and assets unchanged. Modes survive recipes, Undo, portable transfer and reopening; explicit Bake includes their saved result. Older readers reject unknown stored nonnormal fields. This is the declared native policy, not Adobe numerical equivalence.';

const highPassDetails = ' Source-only high_pass takes scalar value=sigma from 0 through 50 with no parameters. Require layerFilterHighPassPolicy=alpha-weighted-residual-128-v1, source coordinates and the individual kind; this policy is independent of Gaussian Blur, Unsharp and Noise capability markers. It builds a gray-centered detail candidate: clamp and half-up round 128 + input RGB - the exact alpha-weighted Gaussian mean, without rounding the mean first. Source edges repeat. Every alpha byte and hidden zero-alpha RGB remain exact. Sigma 0 produces gray 128 at visible source pixels; it is not a bypass. Tiny positive sigma can also produce a gray candidate but retains positive-radius work. Normal shows the detail map; choose Overlay or Soft Light explicitly to blend details into the current RGB. For these two modes gray 128 is byte-neutral after rounding at every opacity; it is not a universal neutral value for all modes. Candidate rounding precedes optional blending and filter opacity. Positive sigma costs 2*(2*ceil(3*sigma)+1)+8 weighted source visits per pixel and uses the existing bounded Gaussian ring; sigma 0 costs one visit with no ring. Any nonnormal blend adds 40. Disabled or zero-opacity entries cost zero. Structurally active zero-sigma entries retain all protection, source-edit and Bake guards. Global adjustments do not include High Pass. Saved scalar values and blend settings survive recipes, Undo, Bake and portable reopening.';
const distortDetails = ' Native fixed-frame four-corner Distort requires layerDistortPolicy=fixed-frame-projective-bilinear-v1, layerDistortCoordinates=stage-pixel-edges and an advertised content type. Corners are strict {x,y} points in TL,TR,BR,BL order, mapping outer pixel edges (0,0),(W,0),(W,H),(0,H) to the same historical stage frame. Coordinates are finite -16384..16384; no auto-fit or canvas enlargement. General mapping requires a stable strictly clockwise convex quad and uses defined binary64 inverse-projective, transparent-edge, alpha-weighted bilinear sampling. Identity and integer translations copy RGBA exactly; general resampling changes samples. No Adobe pixel equivalence, linked Perspective gesture or mesh warp claim. Protected targets reject every mutation. Source filters and their source effect mask precede geometry; additional masks, selection and guides remain in document coordinates. Source-filter selection capture refuses retained Distort, including identity. Every stage costs16 times its frame area under a separate384M cumulative Distort work limit, including copy/identity and hidden layers. Graphs containing Distort also admit a combined256MiB named decoded-frame/candidate/root/retained-group/mask/noise peak before source I/O; encoded data, native codecs and total process memory are outside that limit. Legacy-only admission remains unchanged. Source assets remain immutable, metadata edits are undoable, and portable projects retain the stage. Older readers reject this new transform type. These commands are excluded from edit recipes. Require positive expectedRevision, or the enclosing positive revision inside apply_transaction; never rebase an uncertain retry automatically.';
const localToneDetails = ' Source-only shadows_highlights is Local Shadows / Highlights: value0 and default parameters {shadows:25,highlights:0,shadowWidth:50,highlightWidth:50,sigma:3}. Shadows/Highlights Amounts are0..100 percent and tonal Widths1..100 percent, all in exact0.01 increments; sigma is any finite0..50 source pixels with no positive floor. Partial updates preserve omitted effective settings and explicit zero. Require the independent layerFilterLocalTonePolicy=alpha-weighted-local-tone-v1, source coordinates and individual kind. Existing pointwise shadows/highlights and all global adjustments remain unchanged. It first rounds encoded-RGB Rec709 tone to a byte, then uses the alpha-weighted replicated-edge Q65536 Gaussian neighborhood and rounds its mean to a local byte. Exact bounded tonal-response tables drive an endpoint-preserving rational RGB curve, rounded once before per-entry blending and opacity. Original alpha and hidden RGB are unchanged. Black0 and white255 channel endpoints remain exact; it cannot recover clipped or absent detail. Positive Shadows lifts intermediate channels in dark neighborhoods and Highlights lowers them in bright neighborhoods; widths broaden those supports. A dark pixel surrounded by enough light can receive no shadow lift. This is not edge-aware, hue-preserving or Adobe-equivalent correction; aggressive settings can create halos. Sigma0 classifies each pixel by its own tone. Both Amounts0 bypass candidate computation but nonnormal blending can still change RGB and structural protection/Bake/source-edit guards remain active. Disabled/opacity0 costs0, active dualzero costs1 visit per source pixel, computing sigma0 costs16, positive sigma costs2*(2*ceil(3*sigma)+1)+20, and nonnormal blending adds40. Default sigma3 therefore admits at most6620689 source pixels before other filters, whole-stack mask or memory limits; sigma50 permits617363. The bounded two-channel Gaussian row cache, prepared source row and2KiB tone table join renderer/masked-source/Bake phase admission. LUT setup is separately bounded to512 entries with64-entry yields; no per-pixel BigInt or full luminance plane is retained. A whole-stack effect mask mixes afterward without restricting this filter neighborhood. Recipes and portable projects retain exact parameters; explicit Bake consumes the saved treatment and effect mask while preserving originals, alpha and later masks/geometry.';

const tonalColorDetails = ' Native color_balance uses value0 and parameters shadows/midtones/highlights:[cyanRed,magentaGreen,yellowBlue], each -100..100 in 0.01% increments, plus preserveLuminosity (defaulttrue). Rows defaultzero. Positive controls add red/green/blue. Input encoded-sRGB luma selects triangular tone weights; preservation fits desired chroma to gamut at the original encoded luma, with final byte rounding. Native black_white uses value0 and reds/yellows/greens/cyans/blues/magentas percentages -200..300 in 0.01% increments, default40/60/40/60/20/80. It maps input hue to gray using adjacent color controls. Optional tint(defaultfalse), tintColor(default#b98952) and tintAmount(0..100 in0.01% increments, default100) retain disabled tint settings and preserve the converted gray tone before rounding. Both retain alpha, hidden RGB and ordinary mask/protection rules. Active source filters share a 384-million weighted pixel budget: Color Balance costs 40 per pixel when preserving luminosity or 10 otherwise, and Black & White costs 7; a lone preserved Color Balance filter permits at most 9.6MP. Global adjustment layers follow ordinary canvas limits. These are declared native color algorithms, not Photoshop pixel-parity or linear-light/perceptual luminance claims.';
const details={
  resize_document:'Resize the document and each content layer with retained geometry. Native optional resample is nearest, cubic, mitchell or lanczos3; omission and explicit lanczos3 preserve the legacy default. Inspect documentResizeMethods/documentResizeDefault capabilities. Nearest uses pixel-center sampling and copies all four sampled RGBA bytes exactly at this geometry stage, including hidden RGB and partial alpha. Cubic, Mitchell and Lanczos3 select reduction kernels; these photo methods use cubic enlargement. Earlier filters and source-alpha combination still run before geometry. Additional masks, active/saved selections and guides retain their existing resize rules independently of the chosen image method. Positioned additional masks must be explicitly rasterized before any actual dimension change. Protected content, including hidden layers, permits proportional dimensions only. Source assets and editable text settings remain unchanged; text is rendered at its source size then resampled. Does not resize canvas bounds alone, flatten layers, sharpen, reflow text or use an AI upscaler. Nondefault methods persist as new geometry records that older readers reject. One undo step; transactions supported.',
  set_layer_filter_mask:'Create or replace one source-coordinate effect mask for the complete nonempty raster filter stack. Requires a positive expectedRevision, unprotected raster target, layerFilterMaskPolicy=source-stack-alpha8-v1 and source coordinates plus the applicable advertised source/shape. source is selection, all, none or mask. Supply a strict rectangle/ellipse/bitmap descriptor only for mask; coordinates are source pixels and bitmap dimensions must match the retained source. Bitmap runs are sorted nonoverlapping start,length,alpha triples, at most 600000 scalars, with alpha 1..255; an empty array is black. Explicit shape is required and optional bitmap x/y must be zero. No polygon, positioned wrapper, clip, nested density or image asset is accepted. Current selection captures only exact integer crop/canvas/translation geometry under integer-copy-v1; every resize/resample/noncopy affine rejects rather than approximating an inverse. Intermediate clipped source pixels stay excluded after later padding. Selection capture ignores source alpha, visibility, later masks and groups, bakes its current soft coverage once, and does not change the selection. Null selection rejects; an explicitly empty one succeeds. Set resets enabled=true and density=1. Selection/all/none start feather0/invertfalse; a direct descriptor retains authored feather/invert. Black restores pre-stack working RGB, white keeps the completed filtered RGB and gray mixes them; alpha and hidden RGB stay exact. Blur neighborhoods and entry blend/opacity run before the whole-stack mask. Original source/cutout alpha, later layer masks, geometry and protected/generated exclusions remain separate. Capture has a separate 384-million weighted-work limit and 256 MiB named-buffer bound; polygon edges/rows and bitmap feather preparation count before allocations. Do not lower complexity or retry automatically on refusal. Transactions require a positive outer revision. Mask changes write metadata only, preserve assets and undo in one step. Deleting the final entry, Clear filters and Bake consume the mask; removing only the mask reveals the unchanged full stack. Portable projects retain a strict versioned wrapper that old readers reject. Public filters remains an array with separate read-only filterMask metadata; never reconstruct stored graphs from that projection.',
  modify_layer_filter_mask:'Change saved enabled, feather, invert or density on an existing source filter effect mask without replacing its coverage. Require a positive expectedRevision and at least one field; omitted fields retain their exact values. Feather is finite 0..100 source pixels, density is any finite Number 0..1, and enabled/invert are booleans. Disabling preserves settings and reveals the complete stack; density0 also reveals the complete stack and does not disable filters. Raw source coverage is quantized to alpha8, then the native byte-density expression rounds 255-density*(255-rawByte); raw black at density0.1 becomes230. The final original/filtered RGB mix uses exact alpha8 integer half-up arithmetic. No density precision rounding, alpha multiplication or per-entry scoping is applied. Invalid disabled records still reject. Enabled masks at density>0 over active filters add eight weighted visits per source pixel, including all-black/white masks and hidden layers; ordinary filter work still counts in full. Resource/geometry/source-edit/protection guards remain in force. Changing settings revalidates the complete graph before later raster operations. Recipes cannot contain these mask commands; applying an existing filter-only recipe preserves the target mask, while capturing a masked stack must not discard its scope.',
  clear_layer_filter_mask:'Remove only the shared source filter effect mask from an unprotected raster stack, preserving every filter entry and revealing its full effect. Requires layerFilterMaskPolicy=source-stack-alpha8-v1, the command, a positive expectedRevision and an existing mask; missing mask returns NO_FILTER_MASK. This is distinct from clear_layer_filters, which removes both entries and mask, and from Bake, which materializes the masked result and clears both. One undoable metadata edit, no image reads or writes, transactional with positive outer revision. Original pixels, source/cutout alpha and later layer masks are unchanged.',
  get_mask_preview:'Read an opaque grayscale PNG of native selection, additional-layer-mask or source-filter-mask coverage without changing the document. source=selection (default) requires an active selection; an explicit empty bitmap yields black. source=layer-mask requires layerId and an own mask on any content/group/adjustment node. maskMode=effective (default) includes density; raw evaluates stored feather/inversion/internal clipping before density. layerId/maskMode are invalid for selection. White means full mask coverage, black zero and gray partial; this excludes source alpha, opacity, visibility, ancestor/clipping context and protected-pixel enforcement. This is separate from get_layer_preview view=mask, which shows source cutout alpha. Optional expectedRevision pins the read. maxEdge32..2400 default700 limits the longest edge with no enlargement; nearest pixel-center sampling can omit fine details in reduced previews. Returns source dimensions, exact rendered dimensions, revision and source identity with an image block. For alpha8 coverage only the selected verified mask asset is read; no RGB image source reads, model calls, asset writes or history entry. source=filter-mask requires layerId and the exact source-stack-alpha8-v1 mask policy. Its frame is the retained raster source size before transforms, returned as coordinates=source and sourceWidth/sourceHeight, which can differ from the document. Raw reports saved feather/inversion before density/enable; effective reports the exact alpha8 weights used for original-versus-filtered RGB mixing. Disabled or density0 effective coverage is white while raw remains inspectable. Black means original colors, white the full filter effect; neither mode includes source/cutout alpha, later masks, opacity or geometry.',
  save_edit_recipe:'Save or fully replace one reusable native edit recipe. Supply name, slots and ordered steps; recipeId selects an existing definition to overwrite, otherwise a fresh ID is returned. Version1 is implicit. A slot has a unique safe key, optional label, and type raster/text/content/adjustment; adjustment also requires its fixed kind. Each step is {command,target:slotKey,args}. Allowed commands are add_layer_filter, update_adjustment (required value and fully normalized kind parameters), update_text styling only, set_layer_effects and set_layer_outline. Text content/coordinates, masks, image data, geometry, protection toggles, scripts, nested transactions/recipes and AI are excluded. Filters append; later steps cannot reference their new IDs. Definitions contain no layer bindings. Limits16 recipes,30 steps,16 used slots,32KiB per normalized recipe and256KiB library. One undoable metadata change, no image reads/writes. Not allowed inside apply_transaction.',
  get_edit_recipe:'Read an independent canonical recipe definition and informational SHA-256, pinned to the returned document revision. The full library also appears as editRecipes in get_document. No history, cache, asset, render or model work. The hash is not an application authorization token. Native-only.',
  rename_edit_recipe:'Rename a saved native edit recipe without changing its slots or steps. One undo step; applied edits stay independent. Not allowed inside apply_transaction.',
  delete_edit_recipe:'Delete a saved native edit recipe definition. Already applied filters, typography and styles remain ordinary independent edits. One undo step; not allowed inside apply_transaction.',
  validate_edit_recipe:'Check one saved recipe against explicit bindings {slotKey:currentLayerId}. Bind every declared slot exactly once to distinct layers of its declared type/kind; names and selected layers are never inferred. Returns a revision-bound metadata-only report with valid, issues, changes and binding identity. Runs the same staged native mutations and cumulative graph/project limits as apply, without publishing, rendering, reading/writing image assets, or changing history/cache. Expected target/protection/limit failures return valid:false; missing documents/recipes or stale requested revisions remain command errors. This is not a raster preview or a promise of visible pixel changes or future disk availability.',
  apply_edit_recipe:'Apply all steps of a saved native edit recipe atomically to explicit typed target bindings. Positive expectedRevision is required and pins both the definition and current target state. Prior validate_edit_recipe is useful but not mandatory; application repeats every check and commits once, with one undo step. Returns document, recipeId and appliedSteps count. Filters append to existing stacks; partial text styling preserves omitted values and explicit tracking0/leading:null reset spacing. Actual text, masks, geometry, selections, protection and immutable image sources remain intact. Use a stable requestId for an uncertain-response retry with the identical body. Dedupe is session-only: after restart an already-applied revision safely rejects as stale. Inspect/reconcile; never automatically rebase the retry or use a fresh ID. A deliberate later application intentionally repeats the edits. No model calls, pixel asset writes or nested apply_transaction.',
  get_preview:'Returns an actual rendered image for visual inspection. Use after edits. Preview coordinates may differ from full document coordinates; use document width/height for operations.',
  get_layer_preview:'Inspect one native layer as an actual PNG: view=layer renders isolated layer appearance, source shows its retained imported original, mask shows source cutout alpha before geometry transforms. Use source and mask to identify missed accessories and inspect edge quality before placement. Read-only; unavailable views reject explicitly. Preview coordinates may be scaled; inspect returned dimensions and source/document dimensions.',
  set_layer_fill:'Set editable native layer content Fill opacity. Requires current positive expectedRevision, layerId and finite fillOpacity0..1. Discover layerFillPolicy=content-alpha-outside-effects-v1, supported layerFillContentTypes and this command. Supported raster/solid/text/shape/path/gradient content only. Fill fades the filtered/transformed body while retaining its existing outside outline, shadow and glow; overall Opacity fades both. Fill0 hides the body but may retain outside decoration. Original source pixels, alpha, masks and filters remain unchanged. No early alpha-byte rounding. Groups/global adjustments and nonunit Fill on clipping participants are refused. Changing protected Fill requires explicit unprotection. Existing style presets/recipes do not capture Fill and retain the target value. Source-alpha selection ignores Fill; displayed previews, composite sampling, flattened export and generation snapshots include it. Editable .prism retains Fill; strict layered PSD export refuses nonunit Fill. Atomic transactions require positive outer expectedRevision. Native policy does not claim Photoshop special Fill/blend parity.',
  set_layer_effects:'Replace editable native outside layer effects. effects.shadow supports color, opacity0..1, blur0..64, x/y offsets-256..256; effects.glow supports color, opacity0..1, blur0..64. Omitted fields use sensible defaults. effects:null or {} clears styles while retaining layer Fill. Content layers only. Effects stay outside original nonzero-alpha pixels to preserve subjects; they use canvas-pixel units and remain undoable. Inner styles, bevel and Photoshop-identical rendering are not implemented.',
  set_group_compositing:'Set native group mode and blend atomically. Pass-through lets child adjustments/blends affect the existing backdrop and requires normal group blending. Isolated renders children on transparency, then combines the result once using group opacity/mask and the selected native blend. Omitted blendMode defaults normal. Check groupModes/groupBlendModes capabilities. Any actual mode change rejects while the group contains protected descendants, including hidden ones. Protected content requires normal fully opaque ancestors; moving it across a different isolation context also rejects. Nonempty isolated groups cannot be ungrouped until explicitly changed to pass-through. No group transforms/effects or Photoshop-identical blend guarantee. One undo step.',
  add_guide:'Add a document-local layout guide without changing rendered pixels or image assets. Horizontal means y-position from0 through canvas height; vertical means x-position from0 through canvas width. Positions are whole document pixels and boundary guides are allowed. Maximum64 guides; coincident guides are allowed and retain independent UUIDs. Inspect document.guides. Guides persist through undo/reopen/.prism and transform with canvas crop/resize/bounds. Rulers, guide visibility and snapping are browser preferences, not exported image content.',
  update_guide:'Move one saved native guide to an integer document-pixel position while retaining its ID, axis and order. Horizontal uses y/height; vertical uses x/width. Canvas boundaries are inclusive. This changes metadata only and creates one undo step. Read document.guides and use the latest expectedRevision.',
  delete_guide:'Remove one native document guide by guideId without changing any layer, mask, source asset or rendered pixel. Undo restores it.',
  set_clipping_chain:'Set an exact native clipping chain without reordering. baseLayerId identifies an unprotected, non-generated content base. layerIds contains 0–63 unique direct sibling content layers immediately above it, in bottom-to-top order; [] releases. Upper colors fill the base silhouette without thickening soft alpha. Base opacity, mask and blend apply once to the assembled chain; upper masks, opacity and blends remain editable. All participants must be unprotected and upper outside styles must be disabled. Generated upper layers retain provenance and lower protected pixels block upper color contribution. Groups and adjustments cannot participate. A base layer preview shows the assembled chain; a member preview shows its isolated clipped contribution. Source/mask previews and explicit layer subject selection retain their source-oriented meaning. Whole-chain grouping is supported; individual participant delete, duplicate, reorder, reparent, extraction, placement and arrangement require release first. Source edits and geometry retain links. Editable .prism transfer preserves clipping; strict PSD export rejects chains. One undo step.',
  clear_guides:'Remove all saved native document guides in one undo step. Leaves artwork and image assets unchanged. Browser view preferences remain separate.',
  save_layer_style:'Capture a reusable independent copy of the native content layer outside outline, shadow and glow. Does not capture filters, masks, transforms, opacity, blend mode, pixels or protection. Requires a nonzero outline or enabled shadow/glow setting; hidden content may be sampled. Optional styleId overwrites an existing preset while retaining its ID and, unless supplied, its name. Up to 32 document-local presets; overwrite remains available at the cap. Inspect document.layerStyles. Saving does not restyle any layer. Units are canvas pixels and presets remain unchanged by canvas resizing.',
  apply_layer_style:'Replace both outside style slots on 1–64 unique native content layers using a saved document.layerStyles entry. A missing outline or effects slot in the preset clears that slot on every target. Protected content is allowed: outside styles preserve its original pixels. Groups and adjustment layers reject, and all targets validate before publication. Copies settings into each target; editing the preset later does not update previously styled layers. Preserves source assets, alpha, masks, filters, opacity, blend modes and transforms. One atomic undo step.',
  rename_layer_style:'Rename a saved native layer style without changing its stable ID, settings or previously styled layers. Presets belong to this document and survive undo, reopening and portable .prism export.',
  delete_layer_style:'Remove one saved native layer style by styleId. Previously styled layers keep their independent settings. Undo restores the preset.',
  create_group:'Create an empty native pass-through layer group. Optional parentId selects an existing group; null or omitted means document root. index is the insertion position among direct siblings, bottom-to-top; omitted means top. Groups preserve normal child compositing at neutral settings. Up to8 nesting levels and64 total nodes. Use set_group_compositing to switch an unprotected subtree to isolated blending. Group transforms remain unsupported.',
  group_layers:'Wrap contiguous direct sibling layers or groups in a new native pass-through group, preserving ordering and rendered pixels. All layerIds must have the same parent and form a contiguous range; subtrees move together. One undo step.',
  ungroup_layer:'Remove a native group while retaining its children, IDs and order. A nonempty group must use pass-through mode, be visible with opacity1 and have no mask so ungrouping cannot silently change appearance. Reset group controls first if needed. Empty groups may always ungroup.',
  move_layer:'Move a native layer or complete group subtree to another group, or parentId:null for document root. Optional index is among direct siblings in bottom-to-top order. Rejects cycles, invalid ancestry, protected content under non-unit opacity or nonnormal group blending, and moving existing protected descendants across a different ordered chain of isolated ancestors. Inspect returned structure and preview after reorganizing.',
  save_selection:'Save an independent, named copy of the active native selection. Requires an active selection. Omit selectionId to create a saved entry, up to16 per document; supply an existing selectionId to replace that saved mask while retaining its ID. name is optional. Saved masks survive undo/reopen and transform with canvas geometry. Inspect document.savedSelections.',
  load_selection:'Restore a saved native selection by selectionId. mode=replace preserves its editable mask exactly; add takes maximum coverage, subtract removes saved coverage from the active selection, intersect keeps their overlap. Combining produces a bitmap mask. Subtract/intersect require an active selection; add with none acts as replace. Source pixels and the saved entry remain unchanged.',
  load_layer_selection:'Load a native selection from one layer without segmentation or generation. source=content (default) uses transformed working pixel alpha, including source cutout alpha, before additional masks, opacity, visibility, styles, ancestors, clipping-chain context and dynamic protection exclusions. Supports raster, solid, text, shape, path and gradient; groups/adjustments can supply only their own layer-mask. source=layer-mask requires an existing additional mask: maskMode=effective (default) includes density; raw evaluates stored feather/inversion/internal clipping before density. maskMode is invalid for content. Materializes alpha8, then invert=true complements each byte, then mode=replace/add/subtract/intersect uses existing selection combine math. Subtract/intersect require an active selection; add without one replaces. Empty results remain explicit empty selections. Loading changes no source pixels or layer properties and cannot bypass protections on later edits. One undoable operation; supports transactions and expectedRevision. Inspect layerSelectionSources/MaskModes/ContentTypes capabilities.',
  rename_selection:'Rename a saved native selection without changing its mask or the active selection. Use a selectionId from document.savedSelections. Undoable.',
  delete_selection:'Delete one saved native selection entry. Does not alter the active selection or source pixels. Undo restores the named mask.',
  align_layers:'Align native content layers using integer translations only, preserving source pixels and proportions. axis=horizontal with alignment=start/center/end means left/center/right; vertical means top/middle/bottom. relativeTo=canvas (default) allows one or more layers; layers aligns 2+ against their combined alpha bounds. Bounds exclude outside styles. Targets must be visible content leaves with no layer mask and no hidden/masked/faded or isolated ancestor; protected cutouts and neutral nested leaves are supported. Rejects any content shifted outside the canvas. One undo step; center rounding at most half a pixel.',
  distribute_layers:'Distribute 3+ native content layers horizontally or vertically by centers or equal gaps (default). Orders by current center with document-order ties and fixes the outermost layers. Integer translations preserve source pixels; spacing may differ by 1 pixel from rounding. Gaps mode rejects insufficient span. Targets and ancestor restrictions match align_layers; no masked/hidden/group/adjustment targets. Does not scale, reorder or repaint cutouts. Inspect the rendered result.',
  add_adjustment:'Add an editable adjustment layer. Native supports rectangle/ellipse/polygon masks, scalar color controls and levels/curves. Exposure -5..5 stops; hue -180..180 degrees; brightness/contrast/saturation/temperature/vibrance/highlights/shadows -100..100; blur 0..50; sharpen 0..10. For levels/curves set value=0 and parameters. Levels uses black,white,gamma,outputBlack,outputWhite; curves uses increasing points from x0 to255 and channel rgb/red/green/blue. Native Channel Mixer and Gradient Map use value=0 with parameters. channel_mixer accepts monochrome and red/green/blue/gray rows [red%,green%,blue%,constant%], each -200..200 in 0.01% increments; omitted rows default identity color/Rec709 gray. monochrome uses the separate gray row while retaining color rows. gradient_map accepts 2–16 ordered {offset:0..1,color:#RRGGBB} stops with exact endpoints0/1 and reverse boolean; default black-to-white maps encoded-sRGB tone to grayscale. It interpolates native encoded-sRGB RGB values without opacity stops or dithering. Both preserve alpha and hidden RGB, and apply captured selection/mask and lower protected-content exclusions. Native also supports invert/grayscale/sepia strength0..100, posterize2..256 integer levels, threshold0..255 integer luminance cutoff (0 is all white), median1..15 odd kernel size, and mosaic1..128 integer block size. Spatial filters preserve existing alpha; all adjustment masks and protected-pixel rules still apply. Active selection scopes edits unless explicit mask overrides.' + tonalColorDetails + curvesDetails + selectiveColorDetails + hueSaturationDetails,
  update_adjustment:'Update an existing native adjustment layer without adding a duplicate. Omitted fields remain unchanged; mask:null removes the mask. Parameters must match the layer kind. Channel Mixer/Gradient Map use value=0; updates merge supplied fields, replacing a complete four-value percent row or complete ordered stop list while retaining omitted rows, stops and switches. Color Balance also requires value0 and replaces supplied complete three-value tone rows; Black & White merges individual hue/tint fields. Omitted fields and disabled tint settings remain saved. Fetch the document to inspect its current kind, value and parameters.' + curvesDetails + selectiveColorDetails + hueSaturationDetails,
  add_layer_filter:'Append an editable filter to an unprotected native raster layer. Inspect layerFilterKinds capability: 32 kinds include scalar color adjustments, levels, curves, channel_mixer, gradient_map, median, mosaic, source Gaussian blur and source RGB sharpen. Channel Mixer and Gradient Map use value=0 and the same parameter contracts as add_adjustment; both preserve alpha and hidden RGB. The stack executes first to last on source pixels before geometry; median/mosaic sizes scale with the layer. Preserves alpha and immutable assets. value uses the same ranges as add_adjustment; optional enabled defaults true and opacity defaults 1. Active selection is not captured automatically. Use set_layer_filter_mask explicitly to scope the completed stack without hiding the layer; the additional layer mask separately controls visibility. Source blur uses value=sigma 0..50; source sharpen uses sigma 0..10 with fixed RGB unsharp amount1 and threshold0. Neither accepts parameters. Inspect layerFilterSpatialPolicy=alpha-weighted-gaussian-rgb-v1. These source-only algorithms preserve every alpha byte and zero-alpha RGB, weight neighbors by alpha, and replicate source edges. Blur changes interior color, not cutout coverage. The symmetric quantized Gaussian uses radius ceil(3*sigma); tiny positive sigma can quantize to identity, and zero is an identity candidate before optional filter blending. Sharpen uses a single rounded RGB residual, unlike the unchanged global LAB adjustment. Filter opacity mixes the rounded candidate afterward in Normal mode; optional filter blending precedes opacity. Active identities retain all protection/source-edit/bake-prefix guards. Positive source blur/fixed-sharpen entries cost (2*(2*ceil(3*sigma)+1)+8) source-pixel visits under the shared384-million budget; active sigma0 costs1. At sigma1 one otherwise unfiltered source permits17,454,545 pixels; sigma10 permits2,953,846; blur50 permits629,508 before other limits. A bounded rolling cache also contributes to render and bake memory checks. Maximum 8 entries per layer and 64 per document, subject to processing limits. Returns a stable filter ID in document.layers[].filters. No implicit baking. An existing shared filter effect mask remains attached and scopes the completed stack, including this appended entry; require its exact mask policy when editing a masked target. Distinct source-only unsharp_mask requires value0 and parameters {amount:100,sigma:1,threshold:0} by default. Amount is0..500 percent in exact0.01% increments, sigma is true0..50 source pixels, threshold is an integer0..255. Inspect layerFilterUnsharpPolicy=rgb-residual-threshold-v1 and source coordinates; this marker fully defines the Gaussian/residual policy independently of the old spatial marker. Each RGB sharpening candidate changes only when the absolute unrounded original-minus-Gaussian difference is strictly greater than threshold; equality retains that input channel in the candidate. The residual is scaled by amount/100, clamped and rounded once, then filter opacity blends afterward. Alpha and hidden RGB stay exact. Amount100/threshold0 equals source sharpen at shared sigma0..10. This is not a global adjustment kind or Adobe algorithm identity. Positive nonidentity Unsharp costs2*(2*ceil(3*sigma)+1)+40 visits per source pixel, uniformly across amount settings. Amount0, sigma0 or threshold255 is computational identity with cost1 and no Gaussian cache, but remains structurally active. Disabled/opacity0 costs0. Original assets remain unchanged. Source-only add_noise uses value0 and parameters {amount:5,distribution:uniform,monochromatic:true,seed:1} by default. Amount is0..400 percent in exact0.01% increments; distribution is uniform or gaussian; monochromatic is boolean; seed is integer0..4294967295 including both endpoints. Require layerFilterNoisePolicy=seeded-rgb-discrete-v1 plus source coordinates and individual kind. The saved seed anchors deterministic samples to original source pixel/channel coordinates; previews, exports, Undo, recipes and reopening never reseed. Uniform uses a symmetric midpoint range approaching plus/minus255*amount/100; Gaussian uses that scale as approximately one standard deviation with4096 fixed discrete quantiles and bounded3.668335-sigma tails. Equal Amount differs in spread between distributions. Monochromatic shares the preclamp RGB delta and can still change hue after clipping; it does not convert to grayscale. Add the exact delta, clamp and round once, then apply filter opacity. Alpha and zero-alpha RGB remain exact and alpha skipping never shifts later samples. All positive-amount modes cost8 source-pixel visits, active amount0 costs1 with no candidate/sampling, disabled or opacity0 costs0. Computing Gaussian also reserves one shared4KiB table across render and Bake phases. Native rendering never uses fresh randomness; change seed explicitly to choose a new pattern.' + tonalColorDetails + highPassDetails + localToneDetails + filterBlendDetails + curvesDetails + selectiveColorDetails + hueSaturationDetails,
  update_layer_filter:'Change value, parameters, enabled, opacity or blendMode of one native layer filter. Supply layerId and filterId from the current document. Kind is fixed; omitted fields remain unchanged. Any shared source filter effect mask stays attached and scopes the completed stack; require its exact mask policy for a masked target. Channel Mixer/Gradient Map parameters merge by field; supplied percent rows and ordered stop lists replace the entire row/list. Rows are [R%,G%,B%,constant%], -200..200 in 0.01% increments; maps use 2–16 RGB stops from0 to1 and reverse. Color Balance replaces supplied complete three-value tone rows, while Black & White merges individual hue/tint fields and retains disabled tint settings. Source-only Unsharp Mask parameters merge amount/sigma/threshold by field, retaining omitted current values; defaults are100/1/0 on creation. Amount uses0..500 in0.01% increments, sigma0..50, threshold integer0..255; work and memory are revalidated after changes, including leaving an identity. Source-only Add Noise merges amount/distribution/monochromatic/seed by field and preserves explicit false and seed0/maxuint32. It never reseeds an omitted seed; creation defaults are5/uniform/true/1. These parameterized kinds all require value0. Protected layers reject filter edits. The shared384-million source-filter work budget charges Color Balance40 per pixel when preserving luminosity or10 otherwise, and Black & White7; a lone preserved Color Balance filter permits at most9.6MP. Changes revalidate the complete stack. Disabling or opacity zero preserves the exact unfiltered input at that stage. Stack entries remain editable across undo, transforms and project reopening.' + highPassDetails + localToneDetails + filterBlendDetails + curvesDetails + selectiveColorDetails + hueSaturationDetails,
  reorder_layer_filter:'Move a native filter to zero-based execution index within its raster layer. Filters run in the displayed array order, first to last. Reordering may change colors. Requires an unprotected target and latest expectedRevision. One undo step.',
  delete_layer_filter:'Remove one editable native filter by layerId and filterId. Original source and working image assets remain unchanged. Requires an unprotected target. Undo restores the filter and order. If this is the final entry, its shared filter effect mask is removed atomically too; otherwise the mask remains.',
  clear_layer_filters:'Remove every editable filter from one unprotected native raster layer. Restores unfiltered appearance and removes the shared filter effect mask, while retaining additional layer masks, transforms, opacity and styles. Painting, filling, source-alpha repair, subject extraction and cross-document placement require an empty stack; disabling entries alone does not clear them. This command does not bake pixels.',
  bake_layer_filters:'Explicitly replace one native raster layer working RGB with its current source-space filter result including the shared filter effect mask, then remove all filter entries and that effect mask. Positive expectedRevision is required; bake-containing transactions require it on the enclosing transaction. Retains immutable sourceAsset, original working alpha, separate cutout alpha, source dimensions, transforms, additional layer masks/density/position, styles, clipping, groups, selection and provenance. Current admitted composite pixels remain exact. Disabled/zero-opacity entries are discarded without evaluating them; an entirely inactive stack clears metadata without image I/O. An empty stack rejects NO_FILTERS. Protected targets reject. Active baking also rejects any earlier protected content node, including hidden or fully masked nodes, because contextual filter restoration cannot be baked safely; do not unprotect automatically. Original RGB previews remain original. Previously zero-effective-alpha RGB remains ungraded and can become visible after later cutout repair; spatial filters freeze the cutout sampling at bake time. Filter settings cease to be editable in the current state; Undo restores them. Use this explicit action to continue painting/retouching/filling or other supported source edits without discarding the grade. This is distinct from Clear filters and rasterize_layer, and is excluded from metadata-only recipes. Named working buffers are bounded to256MiB, encoded assets to128MiB and existing filter work limits remain; no model/provider calls. Temporary output and newly published assets are cleaned up on prepublication failure. Reuse the exact requestId/body for uncertain session retries, inspect after restart, and never rebase automatically.',
  add_paint_layer:'Create a transparent raster paint layer in the native document. Paint on this layer to preserve image layers underneath.',
  create_repair_layer:'Create an ordinary transparent paint layer immediately above sourceLayerId, an existing native root raster outside any clipping chain. Leaves the source, original assets, filters and upper grades intact. The source may be protected, filtered, hidden or generated; the new layer inherits none of those settings. Full-document protection still blocks painting over protected pixels. Returns document and layerId. Optional newLayerId is a fresh caller-chosen UUID; use it for a create-then-paint transaction with one undo step. Invalid or colliding IDs reject. No model calls or live link to the source. This action does not set sampling automatically through MCP: specify paint_stroke sampleMode=current-and-below and ignoreAdjustments=true for a repair that excludes upper artwork and adjustment layers.',
  paint_stroke:'Apply one undoable brush, pencil, eraser, clone, heal, dodge, burn, blur, sharpen, smudge, sponge, red_eye or color_replace stroke. Points and source use document coordinates with optional pressure0..1. Size is diameter; hardness/opacity0..1. Brush may create a layer without layerId; other tools require an unprotected raster target without a filter stack, including disabled entries. Brush/pencil/color_replace require color; clone/heal require source. Native clone/heal-only sampleMode defaults all (frozen visible composite), current samples frozen transformed working pixels/source alpha before masks/opacity/styles/surrounding layers, and current-and-below renders through the target inclusively but requires an unclipped root raster. Complete lower groups/chains keep their normal semantics. ignoreAdjustments defaults false; true skips standalone adjustment layers in composite samples, retaining source filters, and rejects with current mode. Sampling is frozen for the entire stroke, including healing correction, and refreshed for each later stroke. Source corresponds to the first destination point; the native sampler follows source minus points[0] within that stroke. For aligned sampling across strokes, retain that document-space offset in the caller and send each new first point plus the offset as source. Restart sampling sends the original anchor each time. Preserve fractional coordinates and do not clamp derived source centers: outside neighbors are transparent and partial border samples remain possible. There is no aligned command argument or persisted sample session. Selection and complete-document protected footprints restrict destination writes independently of sample scope. Strength defaults50; negative only for sponge desaturation. Color replacement tolerance defaults48. Healing remains deterministic sampled color matching, not generative removal. Check retouch sampling capabilities; omitted options preserve legacy behavior.',
  rasterize_layer:'Convert a native content layer to raster pixels at its current appearance, with undo. Use only when pixel editing is required; editable text can be preserved using a separate paint layer instead.',
  add_text:'Add editable text with source-canvas coordinates, fontSize in pixels, hex color and supported font/alignment options. Native tracking is an integer -1000..1000 in thousandths of an em (default0), applied by the existing glyph shaper before layer geometry. Native leading is a finite1..2000 source-pixel baseline step; omit or use null for Auto1.2×fontSize. Explicit newlines and blank lines remain authored; no paragraph wrapping or per-character styling. Check textSpacingProperties and unit capabilities before using these native-only fields. Protected original images remain separate layers.',
  update_text:'Revise an existing unprotected native text layer: content, position, font size, color, family, weight, style and alignment. Optional tracking integer -1000..1000 uses thousandths of an em; zero resets it. Optional leading finite1..2000 sets a source-pixel baseline step; leading:null resets Auto1.2×fontSize. Omitted settings retain current values. Changing fontSize scales tracking and Auto leading; explicit leading stays fixed. Settings remain editable, survive undo/reopen and apply before layer transforms. No pair-kerning, mixed styling or paragraph wrapping. Use latest expectedRevision and inspect the rendered result.',
  set_layer_mask:'Apply or remove a native layer mask. Mask shapes are rectangle, ellipse, or polygon, with document-coordinate bounds/points, inward feathering and optional inversion. mask:null removes the mask. Inspect preview after changes.',
  set_layer_mask_position:'Set absolute integer x/y offsets of an existing native additional layer mask, in document pixels (-16384..16384). Moves only mask coverage; source RGB, source cutout alpha and image geometry remain unchanged. Retains the original mask frame, feather, inversion, density and off-canvas coverage for later position-only moves. Initial position is zero. Resetting zero unwraps only when the source frame still matches the canvas and has no bounds-derived clip. Applies to content, group and adjustment masks, including protected targets. Position is independent of layer transforms. Crop translates the retained frame exactly; canvas-bounds changes clip retained support to established old/new canvas overlap. Image resize requires Rasterize mask position first. One undo step; supports transactions. Check layerMaskPositioning, units and operations capabilities.',
  apply_layer_mask_position:'Rasterize an existing positioned additional mask into a normal current-canvas alpha8 bitmap. Samples raw feather/inversion/clipping exactly once; retains layer density separately. Discards off-canvas mask support and quantizes continuous geometric coverage, so composite pixels are not promised bit-identical. Never applies the mask to image pixels or changes source RGB/cutout alpha. No image asset reads/writes or model calls. Requires a positioned mask; Undo restores its entire retained frame and offsets. Use before resize_document when a retained mask frame exists, including hidden/density-zero masks. Painting or morphing that mask performs the same canvas materialization as part of the explicit edit. One undo step; supports transactions.',
  modify_layer_mask:'Refine an existing native additional layer mask by changing feather, invert or density without replacing its geometry. Density is finite 0..1, defaults 1, and is stored on the layer as maskDensity. Effective coverage is 1-density*(1-rawCoverage), after feather/inversion/internal clipping: 0 disables this additional mask, revealing existing source pixels. Source cutout alpha, opacity and generated/protected hard exclusions remain separate. Painting/morphology retain density and edit raw coverage; explicit mask replacement/removal resets it. Supports content, group and adjustment masks. Requires an existing mask. Check layerMaskProperties capabilities.',
  select_region:'Create a native rectangle/ellipse/polygon selection. Rectangles/ellipses require x,y,width,height; polygons require 3..256 points. Supports inward feathering and inversion. Later paint and adjustment commands use this selection.',
  modify_selection:'Refine an existing native selection by setting feather or inversion. Requires an active selection.',
  morph_selection:'Reshape the current native selection using radius 1–100 document pixels and a square neighborhood. expand takes maximum alpha, contract takes minimum alpha, border subtracts the contracted region from the expanded region (both sides), smooth performs opening then closing to remove narrow features. Outside-canvas alpha is zero. Preserves grayscale coverage without thresholding; current feather/inversion/clipping are baked once into the resulting bitmap. Does not change source pixels or saved selections. Requires an active selection; one undo step. Inspect the resulting mask before using it to edit a subject.',
  morph_layer_mask:'Reshape an existing own layer mask with expand, contract, border or smooth and radius 1–100 document pixels. Same square-neighborhood and zero-boundary rules as morph_selection. Supported on content, adjustment and group masks, including protected targets, because it changes mask coverage only. Requires an existing mask; does not change source cutout alpha, source RGB, protection, other masks or the active selection. Raw feather/inversion/clipping are baked once before density; layer maskDensity is retained separately and never baked twice. Undo restores the original editable mask.',
  add_layer_distort: 'Append one editable four-corner Distort after the current layer geometry. Supply the complete corners array; the fixed frame is the layer current document-sized output. Applying does not rewrite or bake source pixels.' + distortDetails,
  update_layer_distort: 'Replace only the complete corners array of one retained Distort. transformIndex is a zero-based position in the full layer.transforms array, not a Distort-only ordinal. The indexed record must be Distort. Any retained stage can be edited, including before later transforms; its original input/output dimensions and every suffix record remain unchanged. Read its width/height for historical coordinates.' + distortDetails,
  delete_layer_distort: 'Remove exactly one retained Distort at transformIndex, the zero-based position in the full layer.transforms array. The indexed record must be Distort. Reevaluate the remaining geometry; fixed stage dimensions keep suffix frames valid. This can change appearance and does not apply an unsaved UI draft.' + distortDetails,
  transform_layer:'Transform a native content layer within the existing canvas. x,y are translation offsets; scaleX/scaleY and rotation apply about canvas center; optional flips. Pixels outside canvas are clipped in rendering. Layer masks stay in document coordinates. Undo restores the previous state.',
  get_histogram:'Read red, green, blue and luminance histograms (256 bins each) of the actual native composite. Fully transparent pixels are omitted. Does not modify the document.',
  add_shape:'Create an editable rectangle, ellipse, triangle, regular polygon, star or line layer. x,y,width,height define its geometry. Fill/stroke are hex colors or null; strokeWidth is pixels; rectangle radius, polygon/star sides and star innerRadius customize geometry. Layer settings are stored under vector.',
  update_shape:'Revise selected fields of an existing editable shape layer. Omitted fields remain unchanged. Layer transforms and masks are preserved.',
  add_path:'Create an editable cubic Bezier path from 2..256 nodes. Each node has x,y and optional absolute in/out control points. Closed controls closure; fill and stroke may be null. Coordinates are on the source canvas.',
  update_path:'Update a path layer. Replace nodes to add/delete/move anchors or change their absolute Bezier controls. Omitted style fields are preserved.',
  add_gradient:'Create an editable gradient layer. kind is linear/radial/angle/reflected/diamond. start/end define direction and extent. Supply 2..16 strictly increasing stops with offset0..1, hex color and optional opacity; first offset0 and last1. Colors interpolate with premultiplied alpha.',
  update_gradient:'Revise an existing gradient layer without rasterizing it. Supply only changed gradient fields.',
  select_color:'Magic-wand selection from the rendered native composite. x,y is the seed. tolerance0..255 uses maximum RGBA channel difference. contiguous=true uses four-connected neighbors; false selects matching pixels anywhere. mode replace|add|subtract|intersect combines with the active selection (Shift/Alt/Shift+Alt in the UI). Stores an editable bitmap selection.',
  fill_area:'Bucket fill or magic erase on a native raster layer. mode=color requires color; erase reduces alpha. Optional x,y restrict to a color region sampled from the composite; omit both to fill the active selection or whole canvas. Flood area intersects the active selection. opacity0..1; tolerance0..255.',
  sample_color:'Read actual composite RGBA and hex color at x,y. radius0..50 optionally averages a square neighborhood using alpha-weighted color. Does not mutate the image.',
  mask_from_selection:'Copy the active selection, including painted or color-region selections, to an existing layer mask. Requires a selection. Preserves the original selection.',
  paint_selection:'Paint actual selection opacity. mode=add,subtract,replace. Points, size, hardness and opacity follow brush semantics. The resulting bitmap selection scopes future edits and survives undo, save, crop and resize.',
  paint_mask:'Paint a layer mask or adjustment mask with add/subtract/replace mode. An absent mask starts empty for add/replace and full for subtract. Use replace for a fresh painted mask. A masked adjustment layer acts as an adjustment brush. This changes the mask, preserving source pixels.',
  apply_transaction:'Apply a sequence of supported document edits atomically as one history step. Each operation has command and args. Set documentId and expectedRevision only on the transaction. Positive expectedRevision is required when any operation bakes layer filters. Bake then paint/retouch is supported under the remaining operation guards; all new assets written in a bake-containing transaction are owned through commit and rolled back on prepublication failure. If any operation fails the document is restored. No nested transactions, imports, exports, saving or undo/redo inside a transaction.',
  export_document:'Export a flattened copy to a new unique file and return its absolute path; the editable project stays unchanged. Native supports PNG, JPEG, WebP and lossless-deflate TIFF, all8-bit sRGB. JPEG matte defaultswhite and accepts a hex matte color; quality1..100 controls JPEG/lossyWebP. WebP accepts lossless:true. Optional density1..1200 pixels/inch is supported by PNG/JPEG/TIFF and never resizes pixels; WebP density rejects. TIFF is flattened, not layered/PSD/high-depth. Check exportFormats/exportOptions/exportDensityFormats capabilities.',
  reorder_layer:'Reorder a native layer or group subtree among its direct siblings, bottom-to-top index. Flat documents retain their original indexing. Use move_layer to change a native parent group.',
  import_color_lookup:'Atomically add or replace a native Color Lookup from original canonical base64 .cube bytes; prefer prism_import_color_lookup_file for a local file. Require colorLookupPolicy=cube3d-f64-trilinear-srgb-v1, cube-3d format and explicit inputSpace=srgb; no color-space inference or conversion. 3D grids 2–33 only, exact identity domain and unit output. A positive expectedRevision is required. target=adjustment uses optional layerId for replacement; target=layer-filter requires layerId and optional filterId for replacement. Replacement preserves IDs, name, mask, opacity, blend, order and enabled/visible state. A new global lookup uses the active selection. One Undo, original assets preserved through .prism/reopen. Transactions require a positive outer revision and at most 4 MiB aggregate decoded lookup imports. Recipe definitions cannot carry lookup dependencies. Keep requestId stable and inspect after an uncertain response; session deduplication is not a durable receipt.',
  import_image:'Import raster bytes as a new native document. Prefer prism_import_file for local files; this tool takes base64 bytes. No SVG, PSD or RAW.',
  save_document:'Save the editable project. Native changes already auto-save.',
  select_subject:'Select the visible subject using the native local segmentation model. Native optionally takes layerId. Inspect and refine the resulting mask before relying on it; automatic segmentation can miss details.',
  extract_subject:'Extract a raster layer subject using local non-generative segmentation. Preserves its source RGB and stores separate alpha coverage. By default hides the original layer and protects the cutout from AI and pixel edits. Inspect hair, hands, shoes and accessories; refine masks if needed.',
  place_layer:'Place visible content from a source document layer into a target rectangle, fitting its complete alpha bounds proportionally. Supply sourceExpectedRevision from the inspected source to reject concurrent source changes. Creates a separate native raster layer with source provenance; protects it by default. Source content under any isolated ancestor rejects; move it to a pass-through context explicitly before placement. No image generation is used.',
  set_layer_outline:'Set an editable outside-only outline on a native raster layer. width=0 removes it. Default white; source pixels remain unchanged.',
  set_layer_protection:'Enable or disable pixel protection for a native content layer. Protected visible pixels are excluded from AI edits locally. Keep protection enabled for people that must retain their original appearance; proportional placement remains available.',
  paint_cutout_mask:'Refine alpha on an extracted cutout without changing its source RGB. Add restores missed source pixels such as shoes, hands or accessories; subtract removes background. Points use document coordinates. Refine the source cutout before placing it into a composition; transformed/placed targets may require returning to their source.',
  resize_canvas:'Expand or crop the native canvas without scaling source pixels. Pick one of nine anchors; added space is transparent. Existing layers, masks and selections move with the anchor. selectPadding=true selects only newly added space, ready for prism_edit_image with scope=selection. Crop/expansion is one undo step.',
  refine_cutout_from_selection:'Refine an extracted source cutout using the active selection, changing alpha only. Add restores missed original details, subtract hides coverage, intersect retains only selected coverage, replace adopts selection coverage. Use lasso, ellipse, rectangle, color or painted selections. Refine before placing or transforming; original RGB and protection remain unchanged. One undo step.',
  delete_layer:'Remove a layer from the editable document. This is reversible with undo.',
};
const lookupDetails = ' Native color_lookup uses value0 and a complete immutable .cube descriptor {asset,bytes,gridSize,inputSpace:srgb,sourceName,title?}. Require colorLookupPolicy=cube3d-f64-trilinear-srgb-v1, cube-3d format, srgb interpretation, advertised limits and the context kind/command. Prefer prism_import_color_lookup_file for a new file. Existing add/update commands can reuse a verified stored descriptor; add requires a complete descriptor, update parameters={} retains it, and any nonempty descriptor update completely replaces it. Opacity/blend remain outside the descriptor. Original files travel with .prism; lookup-bearing recipes are refused.';
const photoFilterDetails = ' Native Photo Filter uses kind photo_filter and value0 in global/source contexts. Require photoFilterPolicy=rgb-transmission-luma-fit-v1, the individual context kind/command and source coordinates for filters. Optional flat parameters: color is exactly a six-digit RGB hex triplet, density is finite0..100 in exact0.01 percent increments, preserveLuminosity is Boolean. Native defaults are color #ff9500, density25, preservation true; uppercase hex canonicalizes lowercase. Sparse updates retain omitted fields; complete canonical recipes reset all three. Colored encoded-RGB transmission keeps black black; preservation restores original encoded Rec709 weighted luma and uses shared chroma compression to fit RGB8 before exact final half-up byte rounding. Final weighted-luma drift is at most half a byte. This is not Kelvin calibration, linear-light optics or Adobe pixel parity. With preservation white and saturated primaries remain unchanged; zero transmitted luma returns the original RGB. Density100 does not mean flat color replacement. Alpha and hidden RGB remain exact. Source candidate blending/opacity precede the completed-stack effect mask and geometry; global Normal/masks/protection remain. Computing source work16 per pixel, proved identity1 (density0, white filter, or gray filter with preservation), inactive0; existing nonnormal blend adds40 and evaluating mask8. Identities still enter blending and structural source/protection guards. No extra image cache or asset dependency. Original assets, Undo, portable records and ordinary recipe semantics are retained.';
for (const name of ['add_adjustment','update_adjustment','add_layer_filter','update_layer_filter']) details[name] += lookupDetails + photoFilterDetails;
const linkedPerspectiveDetails = ' For a linked Perspective edit, first capture the complete current stage corners in TL/TR/BR/BL order. A horizontal move of corner i by delta changes its X to originalX+delta and partner X to originalPartnerX-delta; partner indices are [1,0,3,2]. Vertical movement changes only Y with partners [3,2,1,0]. Both calculations use the same original quad; preserve all six untouched coordinates and submit all four corners. Horizontal/vertical refer to stage axes, including on an already skewed quad. Zero displacement preserves the original quad. Native full-quad bounds, convexity and stability checks still apply. There is no perspective mode/delta argument or new transform type; this is authoring guidance for the existing command, without an Adobe sampler-parity claim.';
for (const name of ['add_layer_distort','update_layer_distort']) details[name] += linkedPerspectiveDetails;
const channelDetails = ' Require native channelSelectionPolicy=composite-byte-alpha-v1, all five channelSelectionChannels, denseMaskPolicy=framed-raw-alpha8-v1, typed limits and the individual command. Measures the final visible composite including filters, adjustments, masks, geometry, styles and protection; the active selection and selected layer do not restrict measurement. Channels red/green/blue/luma/alpha default luma. RGB component coverage multiplies the composite component by alpha and rounds half up. Encoded luma rounds (2126R+7152G+722B)/10000 to a byte first, then multiplies by alpha and rounds again: [14,1,122,128] gives7. Alpha uses the composite alpha byte. invert=true complements the finished coverage last, so fully transparent pixels become fully selected. This is encoded RGB arithmetic, not linear luminance or Adobe pixel parity. No segmentation or generation call.';
details.get_channel_preview = 'Read an opaque grayscale PNG of prospective composite-channel coverage without creating a selection, asset or Undo step.' + channelDetails + ' Optional positive expectedRevision pins the read. maxEdge32..2400 default700 bounds the longest edge without enlargement; nearest pixel-center sampling can omit fine details. Returns a PNG image block with document/revision, channel/invert, source/output dimensions, maxEdge, coveragePolicy and sampling metadata. White means full selection, black zero and gray partial. Preview is before combination. This command renders RGB content; get_mask_preview instead inspects an existing mask.';
details.load_channel_selection = 'Load full-resolution composite-channel coverage as an undoable active selection; source pixels and layer properties remain unchanged.' + channelDetails + ' Requires positive current expectedRevision; mode=replace (default), add (maximum), subtract (active times one minus channel), or intersect (product). Existing continuous feather coverage is combined before final byte rounding. Subtract/Intersect without an active selection refuse before rendering. An all-zero result is an explicit empty selection, not Clear Selection. Exact coverage uses canonical run-length storage when it fits and an immutable framed alpha8 asset otherwise, without thresholding or resizing. Save explicitly with save_selection to retain a named mask. Supports atomic transactions with a positive outer revision and one Undo step. Stable requestId supports same-session replay; inspect current state after an uncertain result and never retry with a new ID automatically. Resource or quota refusals do not weaken the requested edit. Recipes do not embed channel loads or mask assets.';
const colorRangeDetails = ' Require native colorRangePolicy=sampled-rgb-chebyshev-alpha-v1, typed colorRangeLimits and the individual command. colors is1..8 distinct exact #rrggbb swatches, case-normalized to lowercase with authored order retained; duplicates refuse. tolerance and falloff are integers0..255, defaults32/32. Membership uses nearest encoded-RGB Chebyshev distance: full at distance<=tolerance, then a linear falloff with half-up byte rounding; multiply that byte by composite alpha and round half up again. T0/F4/distance1/alpha2 gives1, not2. T+F may exceed255. invert complements the completed byte last, making transparent pixels fully selected. Samples union by nearest distance, never summed. Measures the fresh final visible composite including filters, Fill, masks, geometry, styles and protection, independent of active selection and selected layer. Original pixels remain unchanged; selections do not unlock protected edits. This is native RGB similarity, not semantic detection or Adobe pixel parity. No provider, generation or segmentation call.';
details.get_color_range_preview = 'Read an opaque grayscale PNG of prospective Color Range coverage without changing the selection, history or assets.' + colorRangeDetails + ' Require typed colorRangePreviewLimits; dense-mask authoring capability is not required for this read. Optional positive expectedRevision pins the read. maxEdge32..2400 default700 bounds output without enlargement; nearest pixel-center samples may omit fine detail. Returns a PNG image block with canonical settings, document/revision, source/output dimensions, maxEdge, coveragePolicy and sampling metadata. White means full, gray partial and black zero selection. Preview is before combination and ignores load mode.';
details.load_color_range_selection = 'Load full-resolution Color Range coverage as one undoable active selection.' + colorRangeDetails + ' Requires positive current expectedRevision, denseMaskPolicy=framed-raw-alpha8-v1 and typed denseMaskLimits. mode=replace(default), add(maximum), subtract(active times one minus candidate), or intersect(product). Existing geometric coverage stays continuous until final byte rounding. Subtract/Intersect without a selection refuse before rendering. Zero coverage creates an explicit empty selection, not Clear Selection. Output uses exact canonical RLE or immutable framed alpha8 without thresholding or resizing. Save explicitly with save_selection for a reusable mask. Atomic transactions require positive outer expectedRevision. Stable requestId supports same-session replay; inspect current state after an uncertain result instead of automatically retrying with a new ID. Resource/quota refusal preserves state. Recipes do not capture Color Range settings or outputs.';
details.set_layer_filter_mask += ' When alpha8 appears in layerFilterMaskShapes and denseMaskPolicy=framed-raw-alpha8-v1 is advertised, source=mask can reuse an exact compatible verified immutable alpha8 descriptor with shape, lowercase SHA256 asset, bytes=width*height+32, source width/height, optional zero x/y, feather0..100 and Boolean invert. It is not a path or arbitrary upload. Source-frame dimensions, ownership, protection and capture-geometry checks still apply; geometric-only mask APIs remain unchanged.';
for(const [command,schema]of Object.entries(commandSchemas)){
  const mutating=!readCommands.has(command);
  server.registerTool(`prism_${command}`,{
    title:commandLabels[command],description:details[command]||`${commandLabels[command]}. Use document IDs from prism_list_documents and the latest expectedRevision for edits.`,
    // A raw SDK shape silently strips unknown fields. Keep the public command
    // strict so an unsupported option cannot turn into a different valid edit.
    inputSchema:z.object({backend,...schema.shape,...(mutating?{requestId:z.string().min(1).max(160).optional().describe('Stable identifier for retrying the same edit without duplicating it.')}:{})}).strict(),
    annotations:{readOnlyHint:!mutating && command!=='export_document',destructiveHint:command==='save_document',idempotentHint:!mutating && command!=='export_document',openWorldHint:false},
  },async(input)=>{
    try{
      const {backend:target,requestId,...args}=input;
      if(command==='import_color_lookup') validateCommand(command,args);
      const result=await request('/api/command',{backend:target,command,args,...(mutating?{requestId:requestId||randomUUID()}:{})});
      if(command==='get_preview'||command==='get_layer_preview'||command==='get_mask_preview'||command==='get_channel_preview'||command==='get_color_range_preview'){
        const{data,...metadata}=result;
        return {content:[{type:'text',text:JSON.stringify(metadata)},{type:'image',data,mimeType:result.mimeType}],structuredContent:metadata};
      }
      if(command==='export_document'){
        const directory=path.join(dataDir,'exports');await fs.mkdir(directory,{recursive:true,mode:0o700});
        const safeName=String(result.filename||`image.${args.format}`).replace(/[^a-zA-Z0-9._-]/g,'_').slice(-160);
        const filename=path.join(directory,`${randomUUID()}-${safeName}`);
        await fs.writeFile(filename,Buffer.from(result.data,'base64'),{flag:'wx',mode:0o600});
        const{data,...metadata}=result;
        return textResult({...metadata,path:filename,backend:target,documentId:args.documentId});
      }
      return textResult(result);
    }catch(error){return failure(error);}
  });
}
registerPsdImportTools(server, { companion, dataDir, textResult, failure });
registerColorLookupTools(server, { request, textResult, failure });

server.registerTool('prism_import_file',{
  title:'Import a local image',description:'Import a user-selected local PNG, JPEG, WebP or TIFF into Prism Native. Reads that exact file only, max 30 MiB. Creates a new editable project preserving original bytes.',
  inputSchema:z.object({path:z.string().min(1).max(4096).describe('Absolute local file path supplied or selected by the user.'),name:z.string().min(1).max(200).optional(),requestId:z.string().min(1).max(160).optional()}).strict(),
  annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false},
},async(args)=>{
  try{
    if(!path.isAbsolute(args.path))throw new Error('Use an absolute path to the image.');
    const type={'.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg','.webp':'image/webp','.tif':'image/tiff','.tiff':'image/tiff'}[path.extname(args.path).toLowerCase()];
    if(!type)throw new Error('Supported files are PNG, JPEG, WebP and TIFF.');
    const handle=await fs.open(args.path,'r');
    let bytes;
    try{const stat=await handle.stat();if(!stat.isFile()||stat.size>30*1024*1024)throw new Error('Choose an image file no larger than 30 MiB.');bytes=await handle.readFile();}
    finally{await handle.close();}
    return textResult(await request('/api/command',{backend:'native',command:'import_image',requestId:args.requestId||randomUUID(),args:{name:args.name||path.basename(args.path).slice(0,200),data:bytes.toString('base64'),mimeType:type}}));
  }catch(error){return failure(error);}
});

