server.registerTool('prism_import_project_file',{
  title:'Open a portable Prism project',
  description:'Import an exact user-selected local .prism file as a new editable native document. Retains original assets, layers, groups, masks and saved selections. Starts a fresh undo history and never overwrites an existing document. Maximum256MiB. Supply a stable requestId and reuse it with the identical file/name after an interrupted response; deduplication retains the latest200 import receipts in the companion session.',
  inputSchema:z.object({path:z.string().min(1).max(4096),name:z.string().trim().min(1).max(200).optional(),requestId:z.string().min(1).max(160).describe('Stable ID for this project import. Reuse it for an uncertain-response retry of this exact file and name.')}).strict(),
  annotations:{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false},
},async({path:filename,name,requestId})=>{try{
  if(!path.isAbsolute(filename)||path.extname(filename).toLowerCase()!=='.prism')throw Object.assign(new Error('Use an absolute path to a .prism project file.'),{code:'INVALID_ARGUMENTS'});
  const handle=await fs.open(filename,'r');let data;
  try{
    const stat=await handle.stat();
    if(!stat.isFile()||stat.size<1||stat.size>MAX_PROJECT_BUNDLE_BYTES)throw Object.assign(new Error('Choose a .prism project file no larger than256MiB.'),{code:'LIMIT_EXCEEDED'});
    const buffer=Buffer.alloc(stat.size+1);let total=0;
    while(total<buffer.length){const {bytesRead}=await handle.read(buffer,total,buffer.length-total,null);if(!bytesRead)break;total+=bytesRead;}
    if(total!==stat.size)throw Object.assign(new Error('The project file changed while it was being read. Wait for it to finish saving.'),{code:'INVALID_ARGUMENTS'});
    data=buffer.subarray(0,total);
  }finally{await handle.close();}
  return textResult(await projectRequest(`/api/projects/import${name?`?name=${encodeURIComponent(name)}`:''}`,{data,requestId}));
}catch(error){return failure(error);}});

server.registerTool('prism_get_generation_handoff',{
  title:'Get an image request for this conversation',
  description:'Read a saved Codex image request, with actual input and protection-mask images for edit requests. Materializes immutable local PNG references so the built-in image tool in this conversation can use them. Generate with that built-in tool, then return its selected output file using prism_complete_generation. This tool is for manual jobs only. Worker-owned queued/generating/returning jobs reject handoff; poll them instead. Do not start a second generator for a worker-owned job.',
  inputSchema:z.object({jobId:jobIdSchema}).strict(),
  annotations:{readOnlyHint:false,destructiveHint:false,idempotentHint:true,openWorldHint:false},
},async({jobId})=>{try{
  const {image:input,mask,...metadata}=await request(`/api/ai/jobs/${encodeURIComponent(jobId)}/handoff`);
  const directory=path.join(dataDir,'generation','handoffs',jobId);
  const assets={};const images=[];
  for(const [role,value]of [['input',input],['mask',mask]])if(value){
    const bytes=Buffer.from(value.data,'base64');
    const digest=createHash('sha256').update(bytes).digest('hex');
    await fs.mkdir(directory,{recursive:true,mode:0o700});
    const filename=path.join(directory,`${role}-${digest}.png`);
    try{await fs.writeFile(filename,bytes,{flag:'wx',mode:0o600});}
    catch(error){if(error.code!=='EEXIST')throw error;const previous=await fs.readFile(filename);if(createHash('sha256').update(previous).digest('hex')!==digest)throw Object.assign(new Error('The saved handoff reference does not match its original image.'),{code:'INVALID_IMAGE'});}
    assets[role]={path:filename,mimeType:'image/png'};
    images.push({type:'text',text:role==='input'?'Saved input canvas. Inspect this before editing.':'Protection mask: opaque alpha is protected; transparent alpha permits edits. Prism enforces this mask locally when installing the generated file.'},{type:'image',data:value.data,mimeType:'image/png'});
  }
  const result={...metadata,assets,instructions:'Use the built-in image generation tool in this conversation. Treat request.prompt as the requested image design. For edits inspect the supplied input and mask. Never regenerate protected people as a substitute for their source cutouts; Prism composites the result locally. Return one generated PNG with prism_complete_generation(jobId, path). If generation is unavailable, report it; do not use a separate CLI or API-key fallback.'};
  return{content:[{type:'text',text:JSON.stringify(result)},...images],structuredContent:result};
}catch(error){return failure(error);}});

server.registerTool('prism_complete_generation',{
  title:'Return an image generated in this conversation',
  description:'Attach the selected PNG produced by this conversation’s image generation tool to an awaiting Codex request. Reads that exact local file only, max30MiB. Applies locally with the saved selection/protection mask and current protected layers. If the document changed, retains output for review. Repeating the identical file is safe and does not add another layer; a different file for the same completed job is rejected. Does not call an image provider.',
  inputSchema:z.object({jobId:jobIdSchema,path:z.string().min(1).max(4096).describe('Absolute path to the selected generated PNG artifact from this conversation.')}).strict(),
  annotations:{readOnlyHint:false,destructiveHint:false,idempotentHint:true,openWorldHint:false},
},async({jobId,path:filename})=>{try{
  if(!path.isAbsolute(filename)||path.extname(filename).toLowerCase()!=='.png')throw Object.assign(new Error('Use an absolute path to the generated PNG file.'),{code:'INVALID_ARGUMENTS'});
  const handle=await fs.open(filename,'r');let data;
  try{
    const stat=await handle.stat();const maxBytes=30*1024*1024;
    if(!stat.isFile()||stat.size<1||stat.size>maxBytes)throw Object.assign(new Error('Choose a generated PNG file no larger than30MiB.'),{code:'INVALID_IMAGE'});
    const buffer=Buffer.alloc(stat.size+1);let total=0;
    while(total<buffer.length){const {bytesRead}=await handle.read(buffer,total,buffer.length-total,null);if(!bytesRead)break;total+=bytesRead;}
    if(total!==stat.size)throw Object.assign(new Error('The generated file changed while it was being read. Wait for it to finish saving.'),{code:'INVALID_IMAGE'});
    data=buffer.subarray(0,total);
  }finally{await handle.close();}
  return textResult(await request(`/api/ai/jobs/${encodeURIComponent(jobId)}/complete`,{data:data.toString('base64')}));
}catch(error){return failure(error);}});

await server.connect(new StdioServerTransport());
